package org.apache.commons.math.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.FieldElement;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for Dfp.toDouble()
 */
public class Dfp_toDouble_TriageGen1Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testToDouble_PositiveInfinity() {
        // Assuming Dfp.newInstance(Double.POSITIVE_INFINITY) or similar handles infinity
        Dfp dfp = new Dfp(new Dfp(Double.POSITIVE_INFINITY));
        assertEquals(Double.POSITIVE_INFINITY, dfp.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_NegativeInfinity() {
        Dfp dfp = new Dfp(new Dfp(Double.NEGATIVE_INFINITY));
        assertEquals(Double.NEGATIVE_INFINITY, dfp.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_NaN() {
        Dfp dfp = new Dfp(new Dfp(Double.NaN));
        assertTrue(Double.isNaN(dfp.toDouble()));
    }

    @Test
    public void testToDouble_Zero() {
        Dfp dfp = new Dfp(new Dfp(0.0));
        assertEquals(0.0, dfp.toDouble(), 0.0);

        Dfp negZero = new Dfp(new Dfp(-0.0));
        // Note: checking sign of zero if implementation supports it
        assertEquals(0.0, negZero.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_NormalPositive() {
        Dfp dfp = new Dfp(new Dfp(123.456));
        assertEquals(123.456, dfp.toDouble(), DELTA);
    }

    @Test
    public void testToDouble_NormalNegative() {
        Dfp dfp = new Dfp(new Dfp(-123.456));
        assertEquals(-123.456, dfp.toDouble(), DELTA);
    }

    @Test
    public void testToDouble_LargeExponent() {
        // Test exponent > 1023
        // Using a very large value that would result in Infinity in double
        Dfp dfp = new Dfp(new Dfp("1e400")); 
        assertEquals(Double.POSITIVE_INFINITY, dfp.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_SmallExponent() {
        // Test exponent < -1074 (Underflow to zero)
        Dfp dfp = new Dfp(new Dfp("1e-400"));
        assertEquals(0.0, dfp.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_Subnormal() {
        // Test values in the subnormal range of double (approx 1e-308 to 1e-324)
        Dfp dfp = new Dfp(new Dfp("1e-315"));
        assertEquals(1e-315, dfp.toDouble(), 1e-325);
    }

    @Test
    public void testToDouble_RoundingUpToNextPowerOfTwo() {
        // This test targets the specific branch: if (mantissa == 4503599627370496L)
        // We need a Dfp value that, when processed, results in a mantissa that rounds up.
        // 1.5 in binary is 1.1 (mantissa 1, exponent 0). 
        // We need a value slightly less than a power of 2 that rounds up.
        Dfp dfp = new Dfp(new Dfp(0.9999999999999999)); 
        double result = dfp.toDouble();
        // The logic in the method handles the carry-over for the mantissa
        // We verify it doesn't crash and returns a valid double close to the value
        assertEquals(0.9999999999999999, result, 1e-16);
    }

    @Test
    public void testToDouble_NegativeLargeExponent() {
        // Test the negate ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY branch
        Dfp dfp = new Dfp(new Dfp("-1e400"));
        assertEquals(Double.NEGATIVE_INFINITY, dfp.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_ExponentBoundary_High() {
        // Test exponent slightly above 1023
        Dfp dfp = new Dfp(new Dfp("1.7976931348623157e308")); // Max double
        assertEquals(Double.MAX_VALUE, dfp.toDouble(), 1e290);
    }

    @Test
    public void testToDouble_ExponentBoundary_Low() {
        // Test exponent slightly below -1023 (Subnormal range)
        Dfp dfp = new Dfp(new Dfp("5e-324"));
        assertEquals(5e-324, dfp.toDouble(), 1e-330);
    }
}
